#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>

using namespace std;

typedef __int128_t int128;

struct Line {
    long long a, b;
    int128 y1, y2;
    int id;
};

// Fenwick Tree (Binary Indexed Tree)
struct Fenwick {
    int n;
    vector<int> tree;
    Fenwick(int n) : n(n), tree(n + 1, 0) {}

    void add(int i, int delta) {
        for (++i; i <= n; i += i & -i) {
            tree[i] += delta;
        }
    }

    int query(int i) {
        int sum = 0;
        for (++i; i > 0; i -= i & -i) {
            sum += tree[i];
        }
        return sum;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    long long x1, x2;
    if (!(cin >> n >> x1 >> x2)) return 0;

    vector<Line> lines(n);
    for (int i = 0; i < n; ++i) {
        cin >> lines[i].a >> lines[i].b;
        lines[i].y1 = (int128)lines[i].a * x1 + lines[i].b;
        lines[i].y2 = (int128)lines[i].a * x2 + lines[i].b;
        lines[i].id = i;
    }

    // Ordenação em X1 - epsilon
    // Menor y1 primeiro. Em empate, maior 'a' tem menor (y1 - eps * a), portanto vem primeiro.
    vector<int> order1(n);
    iota(order1.begin(), order1.end(), 0);
    sort(order1.begin(), order1.end(), [&](int i, int j) {
        if (lines[i].y1 != lines[j].y1) {
            return lines[i].y1 < lines[j].y1;
        }
        return lines[i].a > lines[j].a;
    });

    vector<int> pos1(n);
    for (int rank = 0; rank < n; ++rank) {
        pos1[order1[rank]] = rank;
    }

    // Ordenação em X2 + epsilon
    // Menor y2 primeiro. Em empate, menor 'a' tem menor (y2 + eps * a), portanto vem primeiro.
    vector<int> order2(n);
    iota(order2.begin(), order2.end(), 0);
    sort(order2.begin(), order2.end(), [&](int i, int j) {
        if (lines[i].y2 != lines[j].y2) {
            return lines[i].y2 < lines[j].y2;
        }
        return lines[i].a < lines[j].a;
    });

    // Contagem de inversões
    Fenwick ft(n);
    long long inversions = 0;
    for (int i = 0; i < n; ++i) {
        int p = pos1[order2[i]];
        inversions += i - ft.query(p);
        ft.add(p, 1);
    }

    cout << inversions << "\n";

    return 0;
}
